  8	public final class BipartiteGraph {
  9	    private static final int UNCOLORED = -1;
 10	    private static final int FIRST_COLOR = 0;
 11	    private static final int SECOND_COLOR = 1;
 12	
 13	    private BipartiteGraph() {
 14	        // Utility class.
 15	    }
 16	
 17	    static boolean isBipartite(int vertexCount, int[][] edges) {
 18	        return isBipartite(Graph.fromEdges(vertexCount, edges));
 19	    }
 20	
 21	    static boolean isBipartite(Graph graph) {
 22	        int[] colors = new int[graph.vertexCount()];
 23	        Arrays.fill(colors, UNCOLORED);
 24	
 25	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
 26	            if (colors[vertex] == UNCOLORED
 27	                    && !isComponentBipartite(vertex, graph, colors)) {
 28	                return false;
 29	            }
 30	        }
 31	
 32	        return true;
 33	    }
 34	
 35	    private static boolean isComponentBipartite(
 36	            int startVertex,
 37	            Graph graph,
 38	            int[] colors) {
 39	        Deque<Integer> queue = new ArrayDeque<>();
 40	        colors[startVertex] = FIRST_COLOR;
 41	        queue.offer(startVertex);
 42	
 43	        while (!queue.isEmpty()) {
 44	            int currentVertex = queue.poll();
 45	
 46	            for (int neighbor : graph.neighborsOf(currentVertex)) {
 47	                if (colors[neighbor] == UNCOLORED) {
 48	                    colors[neighbor] = oppositeColor(colors[currentVertex]);
 49	                    queue.offer(neighbor);
 50	                    continue;
 51	                }
 52	
 53	                if (colors[neighbor] == colors[currentVertex]) {
 54	                    return false;
 55	                }
 56	            }
 57	        }
 58	
 59	        return true;
 60	    }
 61	
 62	    private static int oppositeColor(int color) {
 63	        return color == FIRST_COLOR ? SECOND_COLOR : FIRST_COLOR;
 64	    }
