 66	    static final class Graph {
 67	        private final List<List<Integer>> adjacencyList;
 68	
 69	        private Graph(List<List<Integer>> adjacencyList) {
 70	            this.adjacencyList = adjacencyList;
 71	        }
 72	
 73	        static Graph fromEdges(int vertexCount, int[][] edges) {
 74	            validateInputs(vertexCount, edges);
 75	
 76	            List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
 77	            for (int vertex = 0; vertex < vertexCount; vertex++) {
 78	                adjacencyList.add(new ArrayList<>());
 79	            }
 80	
 81	            for (int[] edge : edges) {
 82	                int source = edge[0];
 83	                int destination = edge[1];
 84	                adjacencyList.get(source).add(destination);
 85	                adjacencyList.get(destination).add(source);
 86	            }
 87	
 88	            return new Graph(toUnmodifiableAdjacencyList(adjacencyList));
 89	        }
 90	
 91	        int vertexCount() {
 92	            return adjacencyList.size();
 93	        }
 94	
