 96	            return adjacencyList.get(vertex);
 97	        }
 98	
 99	        private static List<List<Integer>> toUnmodifiableAdjacencyList(
100	                List<List<Integer>> adjacencyList) {
101	            List<List<Integer>> immutableAdjacencyList = new ArrayList<>(adjacencyList.size());
102	            for (List<Integer> neighbors : adjacencyList) {
103	                immutableAdjacencyList.add(Collections.unmodifiableList(neighbors));
104	            }
105	
106	            return Collections.unmodifiableList(immutableAdjacencyList);
107	        }
108	    }
