110	    private static void validateInputs(int vertexCount, int[][] edges) {
111	        if (vertexCount < 0) {
112	            throw new IllegalArgumentException("Vertex count cannot be negative.");
113	        }
114	
115	        if (edges == null) {
116	            throw new IllegalArgumentException("Edges cannot be null.");
117	        }
118	
119	        for (int edgeIndex = 0; edgeIndex < edges.length; edgeIndex++) {
120	            validateEdge(edges[edgeIndex], vertexCount, edgeIndex);
121	        }
122	    }
