124	    private static void validateEdge(int[] edge, int vertexCount, int edgeIndex) {
125	        if (edge == null || edge.length != 2) {
126	            throw new IllegalArgumentException(
127	                    "Each edge must contain exactly two vertices. Invalid edge at index "
128	                            + edgeIndex
129	                            + ".");
130	        }
131	
132	        validateVertex(edge[0], vertexCount, edgeIndex);
133	        validateVertex(edge[1], vertexCount, edgeIndex);
134	    }
135	
136	    private static void validateVertex(int vertex, int vertexCount, int edgeIndex) {
137	        if (vertex < 0 || vertex >= vertexCount) {
138	            throw new IllegalArgumentException(
139	                    "Edge at index "
140	                            + edgeIndex
141	                            + " references invalid vertex "
142	                            + vertex
143	                            + " for graph size "
144	                            + vertexCount
145	                            + ".");
146	        }
147	    }
148	
